    serviceHandoff: { heading: 'Commission a maintainable evidence brief', href: '/services/research-briefing', label: 'research briefing service', paragraphs: ['Use claim-level change triggers when scoping a research briefing service; consequential interpretation and publication approval remain editorial decisions.'] },
